use crate::model::Summary;

pub fn run(data: &[u8], limit: i64) -> Summary {
    let mut frames = Vec::new();
    let mut offset = 0usize;

    while offset < data.len() {
        let start = offset;
        let length = data[offset] as usize;
        offset += 1;

        if (length as i64) > limit {
            return Summary {
                frames,
                consumed: start as i64,
                error: 3,
            };
        }

        let end = offset + length;
        if end >= data.len() {
            return Summary {
                frames,
                consumed: start as i64,
                error: 1,
            };
        }

        let payload = &data[offset..end];
        let checksum = payload.iter().fold(0u8, |sum, &byte| sum.wrapping_add(byte));
        if checksum != data[end] {
            return Summary {
                frames,
                consumed: start as i64,
                error: 2,
            };
        }

        frames.push(payload.to_vec());
        offset = end + 1;
    }

    Summary {
        frames,
        consumed: data.len() as i64,
        error: 0,
    }
}

